function validate([v1, v2]) {
  if (v1.length > 1000 || v2.length > 1000) return 'Each list holds at most 1000 values.';
  if (v1.length + v2.length < 1) return 'The two lists hold at least one value in total.';
  const ok = v => Number.isInteger(v) && v >= -2147483648 && v <= 2147483647;
  if (!v1.every(ok) || !v2.every(ok)) return 'Every value is a 32-bit signed integer.';
  return null;
}

