function adapt(input, solve, kit) {
  const [v1, v2] = input;
  const iterator = new solve(v1, v2);
  if (typeof iterator.hasNext !== 'function' || typeof iterator.next !== 'function') throw new Error('ZigzagIterator needs hasNext() and next() methods.');
  const values = [];
  while (iterator.hasNext()) {
    if (values.length >= v1.length + v2.length) throw new Error('hasNext() still returns true after every value was returned.');
    values.push(iterator.next());
  }
  return values;
}

