class ZigzagIterator {
  constructor(v1, v2) {
    this.queue = [];
    if (v1.length > 0) this.queue.push([v1, 0]);
    if (v2.length > 0) this.queue.push([v2, 0]);
  }

  hasNext() {
    return this.queue.length > 0;
  }

  next() {
    const [list, index] = this.queue.shift();
    if (index + 1 < list.length) {
      this.queue.push([list, index + 1]);
    }
    return list[index];
  }
}

