class ZigzagIterator {
  constructor(v1, v2) {
    // Write out the whole zigzag order up front, then walk it with a position.
    this.values = [];
    for (let i = 0; i < Math.max(v1.length, v2.length); i++) {
      if (i < v1.length) this.values.push(v1[i]);
      if (i < v2.length) this.values.push(v2[i]);
    }
    this.pos = 0;
  }
  hasNext() { return this.pos < this.values.length; }
  next() { return this.values[this.pos++]; }
}

