function generate(rand, size) {
  const large = size === 'large';
  const length = () => {
    if (large) return rand() < 0.2 ? Math.floor(rand() * 5) : 900 + Math.floor(rand() * 101);
    return Math.floor(rand() * 6);
  };
  const value = () => {
    if (large) return Math.floor(rand() * 4294967296) - 2147483648;
    if (rand() < 0.05) return rand() < 0.5 ? -2147483648 : 2147483647;
    return Math.floor(rand() * 21) - 10;
  };
  let a = length();
  const b = length();
  if (a + b === 0) a = 1;
  return [Array.from({ length: a }, value), Array.from({ length: b }, value)];
}
